import express from "express";
import axios from "axios";

const app = express();
app.use(express.json());

const deepl = axios.create({
  baseURL: "https://api-free.deepl.com/v2", // Use api.deepl.com for a Pro account
  timeout: 2500,
  headers: {
    Authorization: `DeepL-Auth-Key ${process.env.DEEPL_API_KEY}`,
    "Content-Type": "application/json",
  },
});

app.post("/api/translate", async (req, res) => {
  const { text, targetLanguage, sourceLanguage } = req.body ?? {};

  if (typeof text !== "string" || !text.trim() ||
      typeof targetLanguage !== "string") {
    return res.status(400).json({ error: "text and targetLanguage are required" });
  }

  try {
    const response = await deepl.post("/translate", {
      text: [text],
      target_lang: targetLanguage.toUpperCase(),
      ...(sourceLanguage && { source_lang: sourceLanguage.toUpperCase() }),
    });

    return res.json({
      translatedText: response.data.translations[0].text,
    });
  } catch (error) {
    const timedOut = error.code === "ECONNABORTED";
    console.error("Translation provider request failed", {
      status: error.response?.status,
      code: error.code,
    });

    return res.status(timedOut ? 504 : 502).json({
      error: timedOut ? "Translation timed out" : "Translation service unavailable",
    });
  }
